																							local function fn120(arg, ...)
																								local str19 = tostring(arg or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")

																								if str19 ~= "" then
																									local n73 = 1
																									local v104 = select
																									local str20 = "#"
																									local v105

																									if not (select("#", ...) - 1 - 1 < 0) then
																										v105 = v104(str20, ...)
																									else
																										v105 = v104(str20)
																									end

																									for i2 = n73, v105 do
																										local v106 = tostring
																										local v107 = select
																										local v108 = i2
																										local str21

																										if not (select("#", ...) - 1 - 1 < 0) then
																											str21 = v107(v108, ...)
																										else
																											str21 = v107(v108)
																										end

																										str21 = str21 or ""
																										if not v106(str21):lower():find(str19, 1, true) then
																											continue
																										end
																										return true
																									end

																									return false
																								end

																								return true
																							end

